// Ordinal model of momentary mood (1 Sad, 2 Meh, 3 Happy).
//
//   P(y_i <= k) = logistic(c_k - eta_i),  k = 1, 2
//   eta_i = time_of_day[s] + weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent daily mood, stationary AR(1)
//
// phi lies in (-1, 1) with (phi + 1) / 2 ~ Beta(2, 2), a prior symmetric around
// zero, so the direction of day-to-day carry-over is estimated, not assumed.
//
// Predictors are standardized; missing cells are imputed as N(0, 1) parameters
// (missing at random). Confirmatory factors have normal(0, 0.5) priors; the others
// share a hierarchical shrinkage prior, beta = tau * beta_z.
data {
  int<lower=1> N;                                 // reports
  int<lower=1> D;                                 // calendar days from first to last report
  int<lower=1> R;                                 // days with reports (rows of X)
  int<lower=0> P;                                 // predictors
  array[N] int<lower=1, upper=3> y;
  array[N] int<lower=1, upper=3> slot;            // morning, afternoon, evening
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  array[N] int<lower=1, upper=R> rated_day;       // row of X for each report
  matrix[R, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=R> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;
  array[P] int<lower=0, upper=1> pooled;          // 0: confirmatory factor, 1: shares tau
}
parameters {
  ordered[2] cutpoints;
  sum_to_zero_vector[3] time_of_day;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  // Factors of the confirmatory hypotheses have their own normal(0, 0.5) prior;
  // the others share the scale tau, a hierarchical shrinkage prior. Pooling the
  // confirmatory factors with many null ones would shrink them by about half.
  vector[P] beta;
  for (j in 1:P) {
    beta[j] = (pooled[j] ? tau : 0.5) * beta_z[j];
  }
  // Non-centered AR(1), started from its stationary distribution.
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = time_of_day[slot] + weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[R, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += (X_full * beta)[rated_day];
  }
  cutpoints ~ normal([-1, 1]', 1.5);
  // On a sum-to-zero vector this matches PyMC's ZeroSumNormal(0.5).
  time_of_day ~ normal(0, 0.5);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}
// Secondary outcome: the evening rating of the day, 0 to 10 (coded 1 to 11).
//
//   P(y_d <= k) = logistic(c_k - eta_d),  k = 1, ..., 10
//   eta_d = weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent day effect, stationary AR(1)
//
// The same factors, timing rules, weekday effects and priors as mood.stan
// (confirmatory factors unpooled, the others under shared shrinkage), with ten
// ordered cutpoints. With one rating per day, the day effect is identified
// only through its autocorrelation.
data {
  int<lower=1> N;                                 // days with a rating
  int<lower=1> D;                                 // calendar days from first to last rating
  int<lower=0> P;                                 // factors
  array[N] int<lower=1, upper=11> y;
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  matrix[N, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=N> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;
  array[P] int<lower=0, upper=1> pooled;          // 0: confirmatory factor, 1: shares tau
}
parameters {
  ordered[10] cutpoints;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  // Factors of the confirmatory hypotheses have their own normal(0, 0.5) prior;
  // the others share the scale tau, a hierarchical shrinkage prior. Pooling the
  // confirmatory factors with many null ones would shrink them by about half.
  vector[P] beta;
  for (j in 1:P) {
    beta[j] = (pooled[j] ? tau : 0.5) * beta_z[j];
  }
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[N, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += X_full * beta;
  }
  cutpoints ~ normal(0, 3);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}
# Prior predictive check (protocol Section 2.9.2): what the priors of mood.stan
# imply about the data before any data are seen. Simulated studies of 180 days,
# three slots, 80% of prompts answered and 23 standardized factors, as many as
# the real study has: 5 confirmatory factors with normal(0, 0.5) priors and 18
# others under the shared shrinkage prior.
#
#   Rscript analysis/prior_check.R [--draws 4000] [--seed 1]

args <- commandArgs(trailingOnly = TRUE)
opt <- function(name, default) {
  i <- match(paste0("--", name), args)
  if (is.na(i)) default else args[i + 1]
}
S <- as.integer(opt("draws", "4000"))
set.seed(as.integer(opt("seed", "1")))
days <- 180
P <- 23
P_CONFIRMATORY <- 5

shares <- matrix(NA_real_, S, 3)
max_share <- numeric(S)
abs_confirmatory <- numeric(0)
abs_other <- numeric(0)
day_sd <- numeric(S)
for (s in seq_len(S)) {
  # Ordered cutpoints: normal(-1, 1.5) and normal(1, 1.5), kept when in order.
  repeat {
    cut <- stats::rnorm(2, c(-1, 1), 1.5)
    if (cut[1] < cut[2]) break
  }
  # Sum-to-zero vectors with normal(0, 0.5) on their elements.
  tod <- stats::rnorm(3, 0, 0.5)
  tod <- tod - mean(tod)
  wd <- stats::rnorm(7, 0, 0.5)
  wd <- wd - mean(wd)
  phi <- 2 * stats::rbeta(1, 2, 2) - 1
  sigma <- abs(stats::rnorm(1, 0, 1))
  tau <- abs(stats::rnorm(1, 0, 0.5))
  beta <- c(stats::rnorm(P_CONFIRMATORY, 0, 0.5), tau * stats::rnorm(P - P_CONFIRMATORY))
  abs_confirmatory <- c(abs_confirmatory, abs(beta[seq_len(P_CONFIRMATORY)]))
  abs_other <- c(abs_other, abs(beta[-seq_len(P_CONFIRMATORY)]))
  u <- numeric(days)
  u[1] <- stats::rnorm(1, 0, sigma / sqrt(1 - phi^2))
  for (t in 2:days) u[t] <- phi * u[t - 1] + stats::rnorm(1, 0, sigma)
  xb <- as.numeric(matrix(stats::rnorm(days * P), days, P) %*% beta)
  day <- rep(seq_len(days), each = 3)
  slot <- rep(1:3, days)
  keep <- stats::runif(length(day)) < 0.8
  eta <- (xb[day] + u[day] + tod[slot] + wd[(day - 1) %% 7 + 1])[keep]
  p1 <- stats::plogis(cut[1] - eta)
  p2 <- stats::plogis(cut[2] - eta)
  v <- stats::runif(length(eta))
  y <- 1L + (v > p1) + (v > p2)
  shares[s, ] <- tabulate(y, 3) / length(y)
  max_share[s] <- max(shares[s, ])
  day_sd[s] <- stats::sd(xb + u)
}

q <- function(x, p = c(0.05, 0.5, 0.95)) round(stats::quantile(x, p, names = FALSE), 3)
cat(sprintf("Prior predictive check: %d simulated studies of %d days, %d factors\n", S, days, P))
for (k in 1:3) cat(sprintf("share of %-5s  median %.3f, 90%% interval %.3f to %.3f\n", c("Sad", "Meh", "Happy")[k], q(shares[, k])[2], q(shares[, k])[1], q(shares[, k])[3]))
cat(sprintf("studies with over 90%% of reports in one category: %.1f%%\n", 100 * mean(max_share > 0.9)))
cat(sprintf("studies with over 50%% Sad reports: %.1f%%\n", 100 * mean(shares[, 1] > 0.5)))
for (group in c("confirmatory", "other")) {
  b <- if (group == "confirmatory") abs_confirmatory else abs_other
  cat(sprintf("|beta| per SD, %s factors: median %.3f, 95th percentile %.3f, 99th percentile %.3f\n",
    group, stats::median(b), stats::quantile(b, 0.95), stats::quantile(b, 0.99)))
}
cat(sprintf("SD of the daily linear predictor (factors and day effect): median %.2f, 90%% interval %.2f to %.2f\n",
  q(day_sd)[2], q(day_sd)[1], q(day_sd)[3]))

// Ordinal model of momentary mood (1 Sad, 2 Meh, 3 Happy).
//
//   P(y_i <= k) = logistic(c_k - eta_i),  k = 1, 2
//   eta_i = time_of_day[s] + weekday[w] + x_d' beta + u_d
//   u_d = phi * u_(d-1) + sigma * e_d          latent daily mood, stationary AR(1)
//
// phi lies in (-1, 1) with (phi + 1) / 2 ~ Beta(2, 2), a prior symmetric around
// zero, so the direction of day-to-day carry-over is estimated, not assumed.
//
// Predictors are standardized; missing cells are imputed as N(0, 1) parameters
// (missing at random). Confirmatory factors have normal(0, 0.5) priors; the others
// share a hierarchical shrinkage prior, beta = tau * beta_z.
data {
  int<lower=1> N;                                 // reports
  int<lower=1> D;                                 // calendar days from first to last report
  int<lower=1> R;                                 // days with reports (rows of X)
  int<lower=0> P;                                 // predictors
  array[N] int<lower=1, upper=3> y;
  array[N] int<lower=1, upper=3> slot;            // morning, afternoon, evening
  array[N] int<lower=1, upper=7> weekday;         // 1 = Monday
  array[N] int<lower=1, upper=D> day;
  array[N] int<lower=1, upper=R> rated_day;       // row of X for each report
  matrix[R, P] X;                                 // missing cells hold 0
  int<lower=0> M;
  array[M] int<lower=1, upper=R> miss_row;
  array[M] int<lower=1, upper=P> miss_col;
  real<lower=0> prior_scale;
  array[P] int<lower=0, upper=1> pooled;          // 0: confirmatory factor, 1: shares tau
}
parameters {
  ordered[2] cutpoints;
  sum_to_zero_vector[3] time_of_day;
  sum_to_zero_vector[7] weekday_effect;
  real<lower=-1, upper=1> phi;
  real<lower=0> sigma_day;
  vector[D] z_day;
  real<lower=0> tau;
  vector[P] beta_z;
  vector[M] x_missing;
}
transformed parameters {
  // Factors of the confirmatory hypotheses have their own normal(0, 0.5) prior;
  // the others share the scale tau, a hierarchical shrinkage prior. Pooling the
  // confirmatory factors with many null ones would shrink them by about half.
  vector[P] beta;
  for (j in 1:P) {
    beta[j] = (pooled[j] ? tau : 0.5) * beta_z[j];
  }
  // Non-centered AR(1), started from its stationary distribution.
  vector[D] mood_day;
  mood_day[1] = sigma_day * z_day[1] / sqrt(1 - square(phi));
  for (d in 2:D) {
    mood_day[d] = phi * mood_day[d - 1] + sigma_day * z_day[d];
  }
}
model {
  vector[N] eta = time_of_day[slot] + weekday_effect[weekday] + mood_day[day];
  if (P > 0) {
    matrix[R, P] X_full = X;
    for (m in 1:M) {
      X_full[miss_row[m], miss_col[m]] = x_missing[m];
    }
    eta += (X_full * beta)[rated_day];
  }
  cutpoints ~ normal([-1, 1]', 1.5);
  // On a sum-to-zero vector this matches PyMC's ZeroSumNormal(0.5).
  time_of_day ~ normal(0, 0.5);
  weekday_effect ~ normal(0, 0.5);
  target += beta_lpdf((phi + 1) / 2 | 2, 2);
  sigma_day ~ normal(0, 1);
  z_day ~ std_normal();
  tau ~ normal(0, prior_scale);
  beta_z ~ std_normal();
  x_missing ~ std_normal();
  y ~ ordered_logistic(eta, cutpoints);
}

import { readFileSync } from "node:fs";
import path from "node:path";
import { DatabaseSync, type SQLInputValue } from "node:sqlite";
import { DB_PATH, ROOT } from "./config.ts";

export const db = new DatabaseSync(DB_PATH);
// WAL lets the R analysis read while the server writes.
db.exec("PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000;");
db.exec(readFileSync(path.join(ROOT, "server", "schema.sql"), "utf8"));

// Columns added after the first release: CREATE TABLE IF NOT EXISTS leaves an
// existing table as it was, so they are added here.
const LATER_COLUMNS: [table: string, column: string, definition: string][] = [
  ["daily_logs", "indoor_pm25", "REAL CHECK (indoor_pm25 BETWEEN 0 AND 1000)"],
  ["daily_logs", "indoor_voc", "REAL CHECK (indoor_voc BETWEEN 0 AND 1000)"],
  ["users", "reminder_times", `TEXT NOT NULL DEFAULT '["10:30","15:30","21:00"]'`],
  ["users", "reminders_on", "INTEGER NOT NULL DEFAULT 1 CHECK (reminders_on IN (0, 1))"],
];
for (const [table, column, definition] of LATER_COLUMNS) {
  const columns = (db.prepare(`PRAGMA table_info(${table})`).all() as { name: string }[]).map((c) => c.name);
  if (!columns.includes(column)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
}

export function get<T>(sql: string, ...params: SQLInputValue[]): T | undefined {
  return db.prepare(sql).get(...params) as T | undefined;
}

export function all<T>(sql: string, ...params: SQLInputValue[]): T[] {
  return db.prepare(sql).all(...params) as T[];
}

export function run(sql: string, ...params: SQLInputValue[]) {
  return db.prepare(sql).run(...params);
}

/** Run fn inside BEGIN IMMEDIATE, so check-then-insert sequences are atomic. */
export function transaction<T>(fn: () => T): T {
  db.exec("BEGIN IMMEDIATE");
  try {
    const result = fn();
    db.exec("COMMIT");
    return result;
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

export const nowIso = (): string => new Date().toISOString();
#!/usr/bin/env Rscript
# Fit the mood model for one user and write the results as JSON.
#
#   Rscript analysis/refit.R --db PATH --user ID --out FILE --draws FILE --stan-dir DIR
#                            [--seed N] [--chains 4] [--iter 2000] [--adapt-delta 0.95]
#
# --iter sets both the warmup and the draws per chain. A confirmatory fit that
# fails the convergence checks is rerun with --iter 4000 --adapt-delta 0.99
# (protocol Section 2.9.5).
#
# Reads the database only. Prints nothing on success; errors go to stderr with
# a non-zero exit so the web app can record the failure.

args <- commandArgs(trailingOnly = TRUE)
opt <- function(name, default = NULL) {
  i <- match(paste0("--", name), args)
  if (is.na(i)) {
    if (is.null(default)) stop("missing --", name, call. = FALSE)
    return(default)
  }
  args[i + 1]
}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE))))

suppressPackageStartupMessages({
  library(DBI)
  library(RSQLite)
})
source(file.path(here, "mood.R"))

user <- as.integer(opt("user"))
con <- dbConnect(SQLite(), opt("db"), flags = SQLITE_RO)
invisible(dbExecute(con, "PRAGMA busy_timeout = 10000"))
on.exit(dbDisconnect(con))

started <- Sys.time()
tags <- tag_associations(con, user)
output <- tryCatch(
  {
    ds <- load_dataset(con, user)
    fit <- fit_model(
      ds, file.path(here, "mood.stan"), opt("stan-dir"),
      seed = as.integer(opt("seed", "1")), chains = as.integer(opt("chains", "4")), iter = as.integer(opt("iter", "2000")),
      adapt_delta = as.numeric(opt("adapt-delta", "0.95"))
    )
    results <- summarize_fit(ds, fit, as.numeric(difftime(Sys.time(), started, units = "secs")))
    jsonlite::write_json(whatif_draws(ds, fit), opt("draws"), auto_unbox = TRUE, digits = 6)
    results$tags <- tags
    list(status = "done", message = "", results = results)
  },
  not_enough_data = function(e) list(status = "waiting", message = conditionMessage(e), results = list(tags = tags))
)
jsonlite::write_json(output, opt("out"), auto_unbox = TRUE, digits = NA, na = "null", null = "null")
#!/usr/bin/env Rscript
# Secondary outcome (protocol Section 2.9.6): the evening rating of the day, run
# at the 6- and 12-month analyses rather than continuously.
#
#   Rscript analysis/secondary.R --db PATH --user ID --out FILE [--stan-dir DIR] [--seed N]
#
# Reads the database only and writes a JSON summary: odds ratios per natural
# unit, the posterior probability of each direction, weekday effects, the
# day-to-day carry-over, and convergence diagnostics.

MODEL_VERSION_DAY <- "day-ordinal-ar1-stan-v2"

# One row per day with an evening rating (from the study start), with the same
# factors and timing rules as the model of momentary mood.
load_day_dataset <- function(con, user_id) {
  days <- DBI::dbGetQuery(
    con,
    "SELECT date, day_satisfaction FROM daily_logs WHERE user_id = ? AND date >= ? AND day_satisfaction IS NOT NULL ORDER BY date",
    params = list(user_id, study_start(con, user_id))
  )
  if (nrow(days) < MIN_RATED_DAYS) {
    not_enough_data(sprintf("The day satisfaction model needs %d rated days (so far: %d).", MIN_RATED_DAYS, nrow(days)))
  }
  dates <- as.Date(days$date)
  c(
    list(
      y = as.integer(days$day_satisfaction) + 1L,
      weekday = iso_weekday(dates),
      day = as.integer(dates - min(dates)) + 1L,
      dates = seq(min(dates), max(dates), by = "day"),
      rated_dates = dates
    ),
    build_factors(con, user_id, dates)
  )
}

fit_day_model <- function(ds, stan_file, stan_dir, seed = 1, chains = 4, iter = 2000, prior_scale = 0.5) {
  dir.create(stan_dir, showWarnings = FALSE, recursive = TRUE)
  model <- cmdstanr::cmdstan_model(stan_file, dir = stan_dir, quiet = TRUE)
  missing <- which(is.na(ds$X), arr.ind = TRUE)
  X0 <- ds$X
  X0[is.na(X0)] <- 0
  model$sample(
    data = list(
      N = length(ds$y), D = length(ds$dates), P = ncol(ds$X), y = ds$y, weekday = ds$weekday, day = ds$day,
      X = X0, M = nrow(missing), miss_row = as.array(as.integer(missing[, 1])),
      miss_col = as.array(as.integer(missing[, 2])), prior_scale = prior_scale,
      pooled = as.array(as.integer(!(ds$predictors$field %in% CONFIRMATORY_FIELDS)))
    ),
    seed = seed, chains = chains, parallel_chains = chains, iter_warmup = iter, iter_sampling = iter,
    adapt_delta = 0.95, refresh = 0, show_messages = FALSE, show_exceptions = FALSE
  )
}

summarize_day_fit <- function(ds, fit) {
  vars <- c("cutpoints", "weekday_effect", "phi", "sigma_day", "tau")
  if (ncol(ds$X)) vars <- c(vars, "beta")
  dr <- posterior::as_draws_matrix(fit$draws(vars))
  diag <- posterior::summarise_draws(fit$draws(vars), "rhat", "ess_bulk", "ess_tail")
  factors <- lapply(seq_len(ncol(ds$X)), function(j) {
    p <- ds$predictors[j, ]
    shift <- as.numeric(dr[, sprintf("beta[%d]", j)]) * p$unit / ds$sds[j]
    p_positive <- mean(shift > 0)
    list(
      field = p$field, label = p$label, unit_label = p$unit_label, lag = p$lag,
      odds_ratio = interval(exp(shift)), p_positive = round(p_positive, 4), evidence = evidence(p_positive)
    )
  })
  list(
    model = list(version = MODEL_VERSION_DAY, draws = nrow(dr), chains = fit$num_chains()),
    data = list(n_days = length(ds$y), first_date = format(min(ds$dates)), last_date = format(max(ds$dates))),
    factors = factors,
    dropped = ds$dropped,
    weekday = lapply(1:7, function(k) list(level = WEEKDAYS[k], effect = interval(as.numeric(dr[, sprintf("weekday_effect[%d]", k)])))),
    dynamics = list(
      phi = c(interval(as.numeric(dr[, "phi"])), p_positive = round(mean(dr[, "phi"] > 0), 4)),
      sigma_day = interval(as.numeric(dr[, "sigma_day"]))
    ),
    diagnostics = list(
      max_rhat = max(diag$rhat, na.rm = TRUE), min_ess_bulk = min(diag$ess_bulk, na.rm = TRUE),
      divergences = sum(fit$diagnostic_summary(quiet = TRUE)$num_divergent)
    )
  )
}

if (sys.nframe() == 0) {
  args <- commandArgs(trailingOnly = TRUE)
  opt <- function(name, default = NULL) {
    i <- match(paste0("--", name), args)
    if (is.na(i)) {
      if (is.null(default)) stop("missing --", name, call. = FALSE)
      return(default)
    }
    args[i + 1]
  }
  here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE))))
  suppressPackageStartupMessages({
    library(DBI)
    library(RSQLite)
  })
  source(file.path(here, "mood.R"))
  con <- dbConnect(SQLite(), opt("db"), flags = SQLITE_RO)
  on.exit(dbDisconnect(con))
  ds <- load_day_dataset(con, as.integer(opt("user")))
  fit <- fit_day_model(ds, file.path(here, "day_satisfaction.stan"), opt("stan-dir", file.path(tempdir(), "stan")), seed = as.integer(opt("seed", "1")))
  jsonlite::write_json(summarize_day_fit(ds, fit), opt("out"), auto_unbox = TRUE, digits = NA, na = "null")
}

// Runs the R analysis and stores what it returns. R reads the database and
// writes JSON; this module is the only one that records runs.
import { execFile } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { sha256 } from "./auth.ts";
import { DATA_DIR, DB_PATH, ROOT, RSCRIPT } from "./config.ts";
import { all, get, nowIso, run, transaction } from "./db.ts";
import { SLOTS, type Slot } from "./study.ts";

const execFileAsync = promisify(execFile);
const ANALYSIS_DIR = path.join(ROOT, "analysis");
const KEEP_FULL_RUNS = 10; // older runs keep only their effect estimates
const RUN_TIMEOUT_MS = 30 * 60 * 1000;
const STALE_MS = 2 * 3600 * 1000;

export type Status = "running" | "done" | "waiting" | "failed";

interface RunRow {
  id: number;
  user_id: number;
  status: Status;
  started_at: string;
  finished_at: string | null;
  n_ratings: number;
  n_days: number;
  data_fingerprint: string;
  results: string;
  message: string;
}

// The results JSON written by analysis/mood.R; see summarize_fit() there for its shape.
export type Results = Record<string, any>;
export type Run = Omit<RunRow, "results"> & { results: Results };

const parse = (row: RunRow | undefined): Run | null => (row ? { ...row, results: JSON.parse(row.results) as Results } : null);

export const getRun = (id: number): Run | null => parse(get<RunRow>("SELECT * FROM analysis_runs WHERE id = ?", id));
export const latestRun = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT 1", userId));
export const latestDone = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT 1", userId));
/** The newest finished run of any kind: tag comparisons exist even before the model can run. */
export const latestFinished = (userId: number): Run | null =>
  parse(get<RunRow>("SELECT * FROM analysis_runs WHERE user_id = ? AND status IN ('done', 'waiting') ORDER BY id DESC LIMIT 1", userId));
export const recentRuns = (userId: number, limit = 10) =>
  all<Omit<RunRow, "results">>(
    "SELECT id, user_id, status, started_at, finished_at, n_ratings, n_days, data_fingerprint, message FROM analysis_runs WHERE user_id = ? ORDER BY id DESC LIMIT ?",
    userId, limit,
  );

export const drawsPath = (runId: number): string => path.join(DATA_DIR, "posteriors", `run_${runId}.json`);

/** Changes whenever the data or the analysis code change, so hourly runs can skip. */
export function fingerprint(userId: number): string {
  const ratings = get("SELECT count(*) AS n, max(created_at) AS t FROM ratings WHERE user_id = ?", userId);
  const logs = get("SELECT count(*) AS n, max(updated_at) AS t FROM daily_logs WHERE user_id = ?", userId);
  const code = ["mood.R", "mood.stan", "refit.R"].map((f) => readFileSync(path.join(ANALYSIS_DIR, f), "utf8"));
  return sha256(JSON.stringify([ratings, logs, code]));
}

/** A run still marked running after two hours was killed midway. */
export function markInterrupted(): void {
  run(
    "UPDATE analysis_runs SET status = 'failed', message = 'Interrupted before it finished.', finished_at = ? WHERE status = 'running' AND started_at < ?",
    nowIso(), new Date(Date.now() - STALE_MS).toISOString(),
  );
}

/** Fit the model for one user. Returns the run, or null when skipped. */
export async function refitUser(userId: number, options: { ifNewData?: boolean } = {}): Promise<Run | null> {
  const dataFingerprint = fingerprint(userId);
  const runId = transaction(() => {
    if (get("SELECT 1 FROM analysis_runs WHERE user_id = ? AND status = 'running'", userId)) return null;
    const last = get<{ data_fingerprint: string }>(
      "SELECT data_fingerprint FROM analysis_runs WHERE user_id = ? AND status != 'running' ORDER BY id DESC LIMIT 1", userId,
    );
    if (options.ifNewData && last?.data_fingerprint === dataFingerprint) return null;
    return Number(run("INSERT INTO analysis_runs (user_id, status, data_fingerprint) VALUES (?, 'running', ?)", userId, dataFingerprint).lastInsertRowid);
  });
  if (runId === null) return null;

  const out = path.join(DATA_DIR, "tmp", `run_${runId}.json`);
  mkdirSync(path.dirname(out), { recursive: true });
  mkdirSync(path.dirname(drawsPath(runId)), { recursive: true });
  try {
    await execFileAsync(
      RSCRIPT,
      [
        path.join(ANALYSIS_DIR, "refit.R"), "--db", DB_PATH, "--user", String(userId), "--out", out,
        "--draws", drawsPath(runId), "--stan-dir", path.join(DATA_DIR, "stan"), "--seed", String(runId),
      ],
      { timeout: RUN_TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 },
    );
    const output = JSON.parse(readFileSync(out, "utf8")) as { status: Status; message?: string; results?: Results };
    const results = output.results ?? {};
    run(
      "UPDATE analysis_runs SET status = ?, message = ?, results = ?, n_ratings = ?, n_days = ?, finished_at = ? WHERE id = ?",
      output.status, output.message ?? "", JSON.stringify(results), results.data?.n_ratings ?? 0, results.data?.n_rated_days ?? 0, nowIso(), runId,
    );
  } catch (error) {
    const stderr = String((error as { stderr?: unknown }).stderr ?? "");
    const lines = stderr.split("\n").filter((l) => l.trim() && !l.includes("built under R version"));
    const message = (lines.slice(-3).join(" ") || String(error)).slice(0, 500);
    run("UPDATE analysis_runs SET status = 'failed', message = ?, finished_at = ? WHERE id = ?", message, nowIso(), runId);
  } finally {
    rmSync(out, { force: true });
  }
  prune(userId);
  return getRun(runId);
}

/** Drop bulky series and posterior draws from older runs. */
function prune(userId: number): void {
  const old = all<{ id: number; results: string }>(
    "SELECT id, results FROM analysis_runs WHERE user_id = ? AND status = 'done' ORDER BY id DESC LIMIT -1 OFFSET ?",
    userId, KEEP_FULL_RUNS,
  );
  for (const row of old) {
    rmSync(drawsPath(row.id), { force: true });
    const results = JSON.parse(row.results) as Results;
    if ("daily_mood" in results) {
      for (const key of ["daily_mood", "ppc", "forecast"]) delete results[key];
      run("UPDATE analysis_runs SET results = ? WHERE id = ?", JSON.stringify(results), row.id);
    }
  }
}

interface Draws {
  cutpoints: number[][];
  time_of_day: number[][];
  weekday_effect: number[][];
  beta: number[][];
  phi: number[];
  sigma_day: number[];
  fields: string[];
  means: number[];
  sds: number[];
}

/** Deterministic standard normals (mulberry32 plus Box-Muller), so answers do not jitter. */
function normals(seed: number): () => number {
  let a = seed >>> 0;
  const uniform = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return () => Math.sqrt(-2 * Math.log(1 - uniform())) * Math.cos(2 * Math.PI * uniform());
}

const logistic = (x: number): number => 1 / (1 + Math.exp(-x));

/**
 * P(Sad, Meh, Happy) per slot on a typical day with the given predictor values
 * (blank means your average). The latent daily mood is averaged over its
 * long-run distribution, so this describes a typical day, not tomorrow.
 */
export function whatIf(runId: number, values: Record<string, string>, weekday: number): Record<Slot, number[]> {
  const file = drawsPath(runId);
  if (!existsSync(file)) throw new Error("The saved posterior for this run is gone; refit first.");
  const d = JSON.parse(readFileSync(file, "utf8")) as Draws;
  const x = d.fields.map((field, j) => {
    const raw = values[field]?.trim();
    if (!raw) return 0;
    const n = Number(raw);
    if (!Number.isFinite(n)) throw new RangeError("Please enter numbers only.");
    return (n - d.means[j]) / d.sds[j];
  });
  const z = normals(1);
  const totals = SLOTS.map(() => [0, 0, 0]);
  for (let s = 0; s < d.phi.length; s++) {
    const stationarySd = d.sigma_day[s] / Math.sqrt(1 - d.phi[s] ** 2);
    const base = x.reduce((sum, xj, j) => sum + d.beta[s][j] * xj, 0) + d.weekday_effect[s][weekday] + stationarySd * z();
    SLOTS.forEach((_, k) => {
      const eta = base + d.time_of_day[s][k];
      const belowMeh = logistic(d.cutpoints[s][0] - eta);
      const belowHappy = logistic(d.cutpoints[s][1] - eta);
      totals[k][0] += belowMeh;
      totals[k][1] += belowHappy - belowMeh;
      totals[k][2] += 1 - belowHappy;
    });
  }
  const round = (v: number) => Math.round((v / d.phi.length) * 1000) / 1000;
  return Object.fromEntries(SLOTS.map((slot, k) => [slot, totals[k].map(round)])) as Record<Slot, number[]>;
}

// Automatic data sources for the hourly job: ring metrics from the Ultrahuman
// Partner API, and indoor air from an Amazon Smart Air Quality Monitor through
// the Alexa web service. Both stay off until configured, and both write to the
// participant's account, the first one created.
//
// Amazon has no public interface for the monitor. The Alexa part follows what
// home automation software does (alexapy for Home Assistant): the account is
// registered once as an Alexa app, the refresh token is kept in ALEXA_FILE, and
// each run exchanges it for web cookies. It can break when Amazon changes things;
// missing days are then handled as missing data.
import { createHash, randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { ALEXA_DOMAIN, ALEXA_FILE, ULTRAHUMAN_TOKEN } from "./config.ts";
import { all, get, run } from "./db.ts";
import { mergeDaily } from "./maintenance.ts";
import { addDays, DAILY_FIELDS, studyDayAndSlot } from "./study.ts";

type Participant = { id: number; time_zone: string };
const participant = () => get<Participant>("SELECT id, time_zone FROM users ORDER BY id LIMIT 1");

/** Calendar date of an instant in a time zone. */
const localDate = (instant: Date, timeZone: string) => studyDayAndSlot(instant, timeZone, 0).studyDate;

const round = (value: number, digits: number) => Math.round(value * 10 ** digits) / 10 ** digits;
const num = (value: unknown): number | undefined => (typeof value === "number" && Number.isFinite(value) ? value : undefined);

const FIELDS = new Map(DAILY_FIELDS.map((f) => [f.name, f]));

/** Drop values outside the field's plausible range (a device sending 0 for "no reading", say). */
export function inRange(values: Record<string, number | undefined>): Record<string, number> {
  const kept: Record<string, number> = {};
  for (const [name, value] of Object.entries(values)) {
    const field = FIELDS.get(name);
    if (value === undefined || !field) continue;
    if ((field.min !== undefined && value < field.min) || (field.max !== undefined && value > field.max)) continue;
    kept[name] = field.type === "int" ? Math.round(value) : value;
  }
  return kept;
}

// ---------------------------------------------------------------- Ultrahuman

const ULTRAHUMAN_URL = "https://partner.ultrahuman.com/api/v1/partner/daily_metrics";

type MetricEntry = { type: string; object: Record<string, any> | null };

/**
 * One day of Partner API metrics as daily log fields. Sleep is filed under the
 * day it ended on, as in the daily log; steps only for finished days.
 */
export function ultrahumanDay(entries: MetricEntry[], finished: boolean): Record<string, number> {
  const by = Object.fromEntries(entries.map((e) => [e.type, e.object ?? {}]));
  const sleep = by.sleep ?? {};
  const minutes = num(sleep.total_sleep?.minutes);
  const pick = (value: number | undefined, digits: number) => (value === undefined ? undefined : round(value, digits));
  return inRange({
    sleep_hours: pick(minutes === undefined ? undefined : minutes / 60, 2),
    sleep_efficiency: pick(num(sleep.sleep_efficiency?.percentage), 1),
    skin_temp_dev_c: pick(num(sleep.temperature_deviation?.celsius), 2),
    hrv_ms: pick(num(by.hrv?.avg), 1),
    resting_hr: pick(num(by.night_rhr?.avg), 1),
    steps: finished ? num(by.steps?.total) : undefined,
  });
}

/** Fetch the last few days of ring metrics; later fetches correct earlier partial values. */
export async function syncUltrahuman(days = 3): Promise<string> {
  if (!ULTRAHUMAN_TOKEN) return "Ultrahuman is off (set ULTRAHUMAN_TOKEN).";
  const user = participant();
  if (!user) return "Ultrahuman: no account yet.";
  const today = localDate(new Date(), user.time_zone);
  let changed = 0;
  for (let back = days - 1; back >= 0; back--) {
    const day = addDays(today, -back);
    const response = await fetch(`${ULTRAHUMAN_URL}?${new URLSearchParams({ date: day })}`, {
      headers: { Authorization: ULTRAHUMAN_TOKEN, Accept: "application/json" },
      signal: AbortSignal.timeout(30_000),
    });
    if (!response.ok) throw new Error(`Ultrahuman answered ${response.status}${response.status === 401 ? " (token rejected)" : ""}.`);
    const body = (await response.json()) as { data?: { metrics?: Record<string, MetricEntry[]> }; error?: string | null };
    if (body.error) throw new Error(`Ultrahuman: ${body.error}`);
    const metrics = body.data?.metrics ?? {};
    const entries = metrics[day] ?? Object.values(metrics)[0] ?? [];
    if (mergeDaily(user.id, day, ultrahumanDay(entries, day < today))) changed++;
  }
  return `Ultrahuman: ${changed} day(s) updated.`;
}

